output_schema:
Complete research report with executive summary, findings, and recommendations
{
  "report": {
    "title": "string",
    "date": "string",
    "research_question": "string"
  },
  "executive_summary": {
    "key_findings": ["string - 3-5 bullet points"],
    "bottom_line": "string - One sentence answer to research question",
    "confidence_statement": "string - Overall confidence in findings",
    "recommended_actions": ["string - Top 3 recommendations"]
  },
  "detailed_findings": [
    {
      "section_title": "string - Maps to sub-question",
      "finding_summary": "string",
      "supporting_evidence": "string - Narrative with citations",
      "confidence": "high | medium | low",
      "implications": "string"
    }
  ],
  "recommendations": [
    {
      "recommendation": "string",
      "rationale": "string - Why this recommendation",
      "priority": "immediate | short-term | long-term",
      "dependencies": ["string - What needs to happen first"],
      "risks": ["string - Risks of following/not following"]
    }
  ],
  "methodology": {
    "approach": "string - How research was conducted",
    "sources_used": {
      "total": "number",
      "by_type": "object",
      "quality_distribution": "object"
    },
    "limitations": ["string - Research limitations"],
    "assumptions": ["string - Key assumptions made"]
  },
  "appendices": {
    "full_source_list": ["string - Formatted citations"],
    "data_tables": ["object - Any supporting data"],
    "glossary": ["object - Key terms defined"]
  }
}
